import{_ as r,l,o as a,c as t,v as c,p as s,x as o,d as i,i as n,S as C}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"RISC-V CSR 与 ecall","description":"","frontmatter":{"title":"RISC-V CSR 与 ecall","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-csr-ecall.md","filePath":"cs/riscv-csr-ecall.md","lastUpdated":1789023840000}'),p={name:"cs/riscv-csr-ecall.md"};function S(h,e,E,m,u,R){const d=l("Mermaid");return a(),t("div",null,[e[1]||(e[1]=c('<h1 id="risc-v-csr-与-ecall" tabindex="-1">RISC-V CSR 与 ecall <a class="header-anchor" href="#risc-v-csr-与-ecall" aria-label="Permalink to &quot;RISC-V CSR 与 ecall&quot;">​</a></h1><div class="epigraph"><p>整数指令只改通用寄存器与内存；机器状态、陷阱入口、关中断放在 CSR 里，自愿进入更高特权用 `ecall`，不是再来一条 `add`。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume II: Privileged Architecture 整理</footer></div><p>上一课<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>钉死了 RV32I 对 <code>x</code> 寄存器与内存的变换，并把 CSR、系统调用后置。本课不重列 <code>addi</code> 语义，也不从 Linux syscall 号另起。缺口是：<strong>控制与状态寄存器</strong>以及自愿陷入，后课异常入口会用到这些名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>csrrw</code>/<code>csrrs</code>/<code>csrrc</code>（及立即数变体）按 12 位地址读写 CSR，同时把旧值写进 <code>rd</code>。教学需要认识的名字：<code>mtvec</code>、<code>mepc</code>、<code>mcause</code>、<code>mstatus</code>（特权课再讲谁能写）。<code>ecall</code>：同步陷阱，不经 <code>jal</code>，硬件保存 PC、跳到入口。<a href="/cs/exception-interrupt-entry">异常入口</a>展开路径；本课先把指令与 CSR 编号钉进 ISA。</p><p><code>ebreak</code> 给调试器。用户态乱写 CSR 会非法——特权级后置，本课承认「不是谁都能写」。</p><h3 id="ecall-不是函数调用约定" tabindex="-1"><code>ecall</code> 不是函数调用约定 <a class="header-anchor" href="#ecall-不是函数调用约定" aria-label="Permalink to &quot;`ecall` 不是函数调用约定&quot;">​</a></h3><p>没有编译器安排的 <code>ra</code> 与栈帧。返回用 <code>mret</code>/<code>sret</code> 从 CSR 取 PC。把 <code>ecall</code> 当成 <code>jal</code> 到操作系统，会把 ABI 与陷阱混层。</p><p><span class="marginnote">特权手册定义 CSR 地址与 <code>mcause</code> 编码。Patterson/Hennessy 用系统调用说明用户/内核边界，细节在后课。本课不把 SBI 功能表抄完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指令仍 32 位：<code>csr</code> 字段在高 12 位，<code>rs1</code>/<code>rd</code> 位置与 I 型一致。数据通路多一个 CSR 堆（小、偏时序）。<code>ecall</code> 不产生 ALU 结果，只触发控制路径。</p>',11)),(a(),s(C,null,{default:o(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RV32I%5B%22%E6%95%B4%E6%95%B0%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E5%86%85%E5%AD%98%22%5D%20--%3E%20CSR%5B%22CSR%20%E8%AF%BB%E5%86%99%E6%8C%87%E4%BB%A4%22%5D%0A%20%20CSR%20--%3E%20ECALL%5B%22ecall%20%E8%87%AA%E6%84%BF%E9%99%B7%E5%85%A5%22%5D%0A%20%20ECALL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B1%87%E7%BC%96%E4%BC%AA%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课伪指令 <code>csrr</code>/<code>csrw</code> 是这些指令的简写。单周期要为 CSR 加端口与异常 MUX；没有本课，<code>lw</code> 故障无处可跳。中断使能位在 <code>mstatus</code>，采样在后课 PLIC 之前先有软件可写的开关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲分页相关 CSR、不把性能计数器当内容。浮点 <code>fcsr</code> 是同一机制的另一块地址空间。</p><p>后课默认：机器状态在 CSR；<code>ecall</code> 是陷入不是 <code>jal</code>。下一课伪指令把常用序列收成助记符。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSR 用专用指令读写；入口相关寄存器在此命名。</li><li><code>ecall</code> 自愿陷阱，返回靠 <code>mret</code> 一类。</li><li>谁能写 CSR 由后课特权级挡住。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V Privileged Spec。</li></ul>',7))])}const B=r(p,[["render",S]]);export{A as __pageData,B as default};
